*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #f6f3ee;
  --surface: #ffffff;
  --border: #e5ddd3;
  --text: #2c241b;
  --text-secondary: #736b62;
  --text-muted: #9e958b;
  --sage: #6b8f71;
  --sage-light: #eaf1eb;
  --sage-dark: #4a6b4f;
  --amber: #d48d3b;
  --amber-light: #faf0e1;
  --amber-dark: #a86a1f;
  --coral: #d95c4a;
  --coral-bg: #fdedea;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 3px rgba(44, 36, 27, 0.06);
  --shadow-md: 0 4px 12px rgba(44, 36, 27, 0.08);
  --transition: 180ms ease;
}

html {
  font-size: 16px;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 1rem;
}

/* ===== App Shell ===== */
#app {
  width: 100%;
  max-width: 480px;
  padding: 0 0 1.5rem;
}

/* ===== Header ===== */
header {
  padding: 1.5rem 0 0.5rem;
}

.header-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

h1 {
  font-size: 1.85rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text);
}

.subtitle {
  font-size: 0.92rem;
  color: var(--text-secondary);
  margin-top: 0.15rem;
  line-height: 1.4;
}

/* ===== Count Badge ===== */
.count-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 3.2rem;
  padding: 0.25rem 0.7rem;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--sage-dark);
  background: var(--sage-light);
  border: 1px solid var(--sage);
  border-radius: 999px;
  white-space: nowrap;
  transition: background var(--transition), color var(--transition), border-color var(--transition);
}

.count-badge.warning {
  color: var(--amber-dark);
  background: var(--amber-light);
  border-color: var(--amber);
}

.count-badge.alert {
  color: var(--coral);
  background: var(--coral-bg);
  border-color: var(--coral);
}

/* ===== Filters ===== */
.filters {
  display: flex;
  gap: 0.5rem;
  padding: 0.75rem 0 1rem;
  border-bottom: 1px solid var(--border);
  margin-bottom: 0.75rem;
}

.filter-btn {
  flex: 1;
  appearance: none;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text-secondary);
  font-size: 0.875rem;
  font-weight: 500;
  padding: 0.55rem 0.75rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all var(--transition);
  box-shadow: var(--shadow-sm);
  font-family: inherit;
}

.filter-btn:hover {
  border-color: var(--sage);
  color: var(--text);
}

.filter-btn.active {
  background: var(--sage);
  border-color: var(--sage);
  color: #fff;
  box-shadow: 0 1px 4px rgba(107, 143, 113, 0.25);
}

.filter-btn.active[data-filter="expiring"] {
  background: var(--amber);
  border-color: var(--amber);
  box-shadow: 0 1px 4px rgba(212, 141, 59, 0.3);
}

/* ===== Pantry List ===== */
.pantry-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  padding-bottom: 0.5rem;
}

.pantry-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 0.85rem 0.9rem 0.85rem 1rem;
  box-shadow: var(--shadow-sm);
  transition: border-color var(--transition), box-shadow var(--transition);
  animation: itemIn 280ms ease both;
}

@keyframes itemIn {
  from { opacity: 0; transform: translateY(6px); }
  to   { opacity: 1; transform: translateY(0); }
}

.pantry-item:hover {
  border-color: #d6cdc0;
  box-shadow: var(--shadow-md);
}

.pantry-item.used {
  opacity: 0.5;
  text-decoration: line-through;
  pointer-events: none;
}

.pantry-item.used .item-info {
  text-decoration: line-through;
}

.pantry-item.removing {
  opacity: 0;
  transform: translateX(30px);
  transition: opacity 200ms ease, transform 200ms ease;
}

/* ===== Item Content ===== */
.item-icon {
  flex: 0 0 auto;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.3rem;
  background: var(--sage-light);
}

.item-icon.amber-bg {
  background: var(--amber-light);
}

.item-icon.coral-bg {
  background: var(--coral-bg);
}

.item-info {
  flex: 1;
  min-width: 0;
}

.item-name {
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--text);
  line-height: 1.3;
}

.item-meta {
  display: flex;
  gap: 0 0.5rem;
  flex-wrap: wrap;
  align-items: baseline;
  font-size: 0.78rem;
  margin-top: 0.1rem;
}

.item-category {
  color: var(--text-muted);
  text-transform: capitalize;
}

.item-quantity {
  color: var(--text-secondary);
}

.item-expiry {
  color: var(--text-muted);
  white-space: nowrap;
}

.item-expiry.warning {
  color: var(--amber-dark);
  font-weight: 600;
}

.item-expiry.alert {
  color: var(--coral);
  font-weight: 600;
}

/* ===== Mark Used Button ===== */
.mark-btn {
  flex: 0 0 auto;
  appearance: none;
  border: none;
  background: transparent;
  color: var(--text-muted);
  font-size: 0.75rem;
  font-weight: 500;
  padding: 0.3rem 0.6rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
  font-family: inherit;
  line-height: 1;
}

.mark-btn:hover {
  background: var(--sage-light);
  color: var(--sage-dark);
}

.mark-btn:focus-visible {
  outline: 2px solid var(--sage);
  outline-offset: 2px;
}

/* ===== Empty State ===== */
.empty-state {
  text-align: center;
  padding: 3rem 1.5rem;
  color: var(--text-muted);
}

.empty-state p {
  font-size: 0.95rem;
  line-height: 1.6;
}

.empty-state .empty-icon {
  font-size: 2.5rem;
  margin-bottom: 0.75rem;
  opacity: 0.6;
}

/* ===== Footer ===== */
.app-footer {
  text-align: center;
  padding: 1.5rem 0 0;
  font-size: 0.78rem;
  color: var(--text-muted);
  border-top: 1px solid var(--border);
  margin-top: 1rem;
}

/* ===== Responsive ===== */
@media (max-width: 420px) {
  body { padding: 0.5rem; }
  h1 { font-size: 1.6rem; }
  .pantry-item { padding: 0.7rem 0.75rem; }
  .mark-btn { font-size: 0.72rem; padding: 0.2rem 0.5rem; }
}

@media (min-width: 600px) {
  #app { max-width: 520px; padding: 0.5rem 1rem 2rem; }
}
